# Find all nested rectangles by analyzing color regions
def find_rectangles(grid, start_row, start_col, target_color):
    """Find the bounding box of a rectangular region of a color."""
    H, W = len(grid), len(grid[0])
    rows_with_color = []
    for r in range(start_row, H):
        for c in range(start_col, W):
            if grid[r][c] == target_color:
                rows_with_color.append(r)
    if not rows_with_color:
        return None
    min_r = min(rows_with_color)
    if min_r != start_row:
        return None
    for c in range(start_col, W):
        samples = [grid[r][c] for r in range(start_row, min_r+1)]
        if target_color not in samples:
            return None
    # Find full width
    min_c = start_col
    max_c = start_col
    for r in range(min_r, start_row + max(rows_with_color, min(len(rows_with_color), 1))):
        if grid[r][max_c :] and all(grid[r][c] == target_color or grid[r][c] == 0 for c in range(max_c, W)):
            break

    # Simpler: scan for rectangular bounds
    H, W = len(grid), len(grid[0])
    min_r, max_r = -1, -1
    min_c, max_c = -1, -1

    for r in range(start_row, H):
        for c in range(start_col, W):
            if grid[r][c] == target_color:
                if min_r == -1:
                    min_r, min_c = r, c
                max_r, max_c = r, c

    if min_r == -1:
        return None

    return (min_r, max_r, min_c, max_c, target_color)

